// Package catalystcenter implements the "catalyst_center" inventory sync
// plugin: PLAN.md Section 6a's connector for a Cisco Catalyst Center,
// which is the authoritative source for the network devices it manages.
//
// Originally generated by pleiades forge new-plugin
// (internal/forge/pluginscaffold), then implemented against Cisco's public
// DevNet always-on sandbox at sandboxdnac.cisco.com. That sandbox is
// read-only, which is why this plugin is read-only by default rather than
// as an afterthought: a controller owns the devices it manages, so The Pleiades
// imports from it and never writes back.
//
// This is the plugin that justified building the four-method port at all.
// internal/inventory's static YAML plugin deliberately refused to design
// one around a single static-file implementation, on the grounds that one
// consumer is not evidence. This is the second, and it is deliberately
// unalike: it authenticates, it pages, its classification is derived rather
// than declared, and its upstream can disagree with local state.
package catalystcenter

import (
	"context"
	"fmt"
	"strings"

	"github.com/Subject-Void-LLC/the-pleiades/internal/classification"
	"github.com/Subject-Void-LLC/the-pleiades/internal/credential"
	inv "github.com/Subject-Void-LLC/the-pleiades/internal/inventory"
	"github.com/Subject-Void-LLC/the-pleiades/internal/inventory/record"
	"github.com/Subject-Void-LLC/the-pleiades/internal/inventory/syncplugin"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/catalystcenter"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/inventory"
)

// Name is this plugin's registration key and the value stamped into the
// SourceAuthority of every device it syncs.
const Name = "catalyst_center"

func init() {
	syncplugin.MustRegister(syncplugin.Descriptor{
		Name:        Name,
		Description: "reads managed network devices from a Cisco Catalyst Center",
		DefaultConfig: syncplugin.Config{
			Name:     Name,
			Endpoint: "https://sandboxdnac.cisco.com",
			ReadOnly: true,
		},
		// Verified against the real DevNet sandbox: authenticate, page the
		// device inventory, classify, and reconcile. See
		// tests/e2e/catalyst_test.go for the reproducible run.
		Status:              syncplugin.StatusImplemented,
		RequiresCredentials: true,
		New:                 func(deps syncplugin.Deps) syncplugin.Plugin { return New(deps) },
	})
}

// CatalystCenter is the "catalyst_center" sync plugin. The zero value is
// not usable; construct one with New.
type CatalystCenter struct {
	cfg     syncplugin.Config
	client  *catalystcenter.Client
	factory *inv.ItemFactory
	ruleSet *classification.RuleSet

	// creds resolves cfg.CredentialName at Connect time. It arrives
	// through syncplugin.Deps, so it is whatever store the composition
	// root that built this plugin uses, and syncplugin.Open has already
	// refused to build the plugin at all if that store was nil (the
	// descriptor above sets RequiresCredentials).
	creds credential.Store
}

// compile-time proof this plugin satisfies the port.
var _ syncplugin.Plugin = (*CatalystCenter)(nil)

// New creates an unconnected plugin from the dependencies the
// composition root supplies.
//
// It used to take functional Options. WithCredentialStore became
// syncplugin.Deps, which every constructor receives on the one path
// callers build through rather than one caller having to remember it.
// WithClientOption was deleted outright: its doc comment claimed "tests
// use it to point at a stub server", and no caller existed anywhere in
// the module, including the tests, which point at their httptest.Server
// through Config.Endpoint like any other deployment does. A doc comment
// naming a caller that does not exist defeats the exact check somebody
// would run to find one.
func New(deps syncplugin.Deps) *CatalystCenter {
	return &CatalystCenter{
		factory: inv.NewItemFactory(),
		ruleSet: classification.DefaultRuleSet(),
		creds:   deps.Credentials,
	}
}

// Connect resolves the configured credential and authenticates against the
// controller.
//
// It authenticates eagerly rather than lazily, by asking for a device
// count. A Connect that only built a client would report success against a
// wrong password, a wrong hostname, or an unreachable controller, and the
// failure would surface later as a confusing mid-sync error.
func (p *CatalystCenter) Connect(ctx context.Context, cfg syncplugin.Config) error {
	if err := cfg.Validate(); err != nil {
		return err
	}
	if cfg.Endpoint == "" {
		return fmt.Errorf("sync plugin %q: endpoint is required", Name)
	}
	if p.creds == nil {
		// Re-checked here, not only in syncplugin.Open, because Connect is
		// a method on an exported type and nothing stops a caller from
		// building a CatalystCenter directly. The alternative to
		// re-checking is a nil-pointer panic inside Lookup.
		return fmt.Errorf("sync plugin %q: no credential store configured", Name)
	}

	credentialName := cfg.CredentialName
	if credentialName == "" {
		// Default to the plugin's own name so the common single-controller
		// case needs no extra configuration: `pleiades add-credential
		// catalyst_center` is enough.
		credentialName = Name
	}

	cred, err := p.creds.Lookup(ctx, credentialName)
	if err != nil {
		return fmt.Errorf("sync plugin %q: resolving credential %q: %w", Name, credentialName, err)
	}

	var opts []catalystcenter.Option
	if cfg.InsecureSkipVerify {
		opts = append(opts, catalystcenter.WithInsecureSkipVerify(true))
	}

	client, err := catalystcenter.New(cfg.Endpoint, cred.Username, cred.Password, opts...)
	if err != nil {
		return fmt.Errorf("sync plugin %q: %w", Name, err)
	}

	if _, err := client.DeviceCount(ctx); err != nil {
		// Close before returning. This request already opened a pooled
		// connection, and a client that never reaches p.client is a client
		// no later Close can reach either, so a failed Connect would
		// otherwise leak one connection per attempt. A retry loop around a
		// wrong password would leak one every time.
		_ = client.Close()
		return fmt.Errorf("sync plugin %q: connecting to %s: %w", Name, cfg.Endpoint, err)
	}

	p.cfg = cfg
	p.client = client
	return nil
}

// Discover streams the controller itself followed by every device it
// manages.
//
// The controller is included deliberately. It is a real appliance in the
// fleet, it is the target every net.catalyst.* method addresses, and
// emitting it here means a sync leaves inventory in a state where those
// runbooks can run without a separate manual add-host step. It is
// distinguishable from the managed devices by its catalyst_role property,
// which is what Classify keys on.
func (p *CatalystCenter) Discover(_ context.Context) (syncplugin.RecordIterator, error) {
	if p.client == nil {
		return nil, syncplugin.ErrNotConnected
	}
	return newDeviceIterator(p.client, p.cfg.EffectivePageSize()), nil
}

// Classify maps one discovered record onto a device type and capability set
// by deriving a Section 6d classification path and resolving it against the
// rule tree.
//
// Deriving the path is this plugin's whole job here. What the path means,
// which type it assigns, and which capabilities come with it all live in
// internal/classification, so an operator who adds a rule changes behavior
// without touching this file.
func (p *CatalystCenter) Classify(_ context.Context, rec record.Record) (syncplugin.Classification, error) {
	path, reason := classificationPath(rec)
	if path == nil {
		return syncplugin.Quarantine(reason), nil
	}

	// Every device imported from a read-only controller lands
	// simulate-locked rather than active. LifecycleState.CanExecute already
	// returns false for that state, so this is the existing Section 9
	// mechanism doing what it was built for: a device The Pleiades has only
	// read about, and never authenticated to directly, should not accept
	// real work until an admin promotes it.
	state := inventory.StateSimulateLocked
	if !p.cfg.ReadOnly {
		state = inventory.StateActive
	}

	return syncplugin.ClassifyPath(p.ruleSet, path, state), nil
}

// Sync reconciles every discovered device into repo through the shared
// driver.
func (p *CatalystCenter) Sync(ctx context.Context, repo inv.Repository) (syncplugin.Reconciliation, error) {
	if p.client == nil {
		return syncplugin.Reconciliation{}, syncplugin.ErrNotConnected
	}
	return syncplugin.Reconcile(ctx, p, p.cfg, repo, p.factory)
}

// Close releases the REST client's pooled connections and cached token. A
// plugin that was never connected has nothing to release and returns nil.
func (p *CatalystCenter) Close() error {
	if p.client == nil {
		return nil
	}
	err := p.client.Close()
	p.client = nil
	return err
}

// classificationPath derives the Section 6d path for a discovered record,
// or returns nil and a reason explaining why it could not.
//
// The mapping is deliberately conservative. Catalyst Center manages Cisco
// gear, but it reports software types this codebase has no rules for
// (IOS-XR, NX-OS, and third-party devices onboarded through it), and
// guessing at those would produce a device hydrated as something it is not.
// Anything unrecognized is quarantined for manual review, which is what
// Section 6g asks for.
func classificationPath(rec record.Record) ([]string, string) {
	if isController(rec) {
		return []string{"network_device", "cisco", "catalyst_center"}, ""
	}

	softwareType, _ := rec.Properties[propSoftwareType].(string)
	switch strings.ToUpper(strings.TrimSpace(softwareType)) {
	case "":
		return nil, "upstream record reported no software type"
	case "IOS-XE", "IOS":
		if isSwitch(rec) {
			return []string{"network_device", "cisco", "ios", "switch"}, ""
		}
		return []string{"network_device", "cisco", "ios"}, ""
	default:
		return nil, fmt.Sprintf("no classification rule for software type %q", softwareType)
	}
}

// isController reports whether rec is the Catalyst Center itself rather
// than one of the devices it manages.
func isController(rec record.Record) bool {
	role, _ := rec.Properties[propCatalystRole].(string)
	return role == roleController
}

// isSwitch reports whether rec describes a switch rather than a router.
//
// Catalyst Center's own family field is the signal, not its role field:
// role describes topology position ("ACCESS", "CORE", "BORDER ROUTER"),
// and an access-role device is not necessarily a switch. Family is what
// actually says what the box is.
func isSwitch(rec record.Record) bool {
	family, _ := rec.Properties[propFamily].(string)
	return strings.Contains(strings.ToLower(family), "switch")
}
